(function(){const urlParams=new URLSearchParams(window.location.search);const utmParams=['utm_source','utm_campaign','utm_location','utm_adgroup'];utmParams.forEach(param=>{if(urlParams.has(param)){sessionStorage.setItem(param,urlParams.get(param))}});document.addEventListener("DOMContentLoaded",function(){utmParams.forEach(param=>{const inputElement=document.getElementById(param);if(inputElement){const savedValue=sessionStorage.getItem(param);if(savedValue){inputElement.value=savedValue}}})})})()